#ifndef SHOWAI_BOUNDARY_VERTEX_TEST_API_HPP
#define SHOWAI_BOUNDARY_VERTEX_TEST_API_HPP
#include "owner.hpp"
namespace showai_boundary_vertex_test{
using namespace showai_boundary;
struct Writer{uint32_t values[4096]{},size=1;bool good=true;void word(uint32_t x){if(size==4096){good=false;return;}values[size++]=x;}void wide(uint64_t x){word(uint32_t(x));word(uint32_t(x>>32));}void rational(const Q&q){word(uint32_t(q.sign()));word(q.numerator().size());word(q.denominator().size());for(uint32_t i=0;i<q.numerator().size();i++)word(q.numerator().data()[i]);for(uint32_t i=0;i<q.denominator().size();i++)word(q.denominator().data()[i]);}void polynomial(const Polynomial&p){word(p.coefficients.size());for(const auto&q:p.coefficients)rational(q);}void root(const Root&r){polynomial(r.definition());rational(r.lower);rational(r.upper);}void certificate(const Record<VertexCertificate>&record){word(record.valid()?1:0);if(!record.valid())return;const auto&v=*record.get();wide(v.revision);wide(v.point.get()->identity);word(v.point.get()->exact()?1:0);if(v.point.get()->exact()){rational(v.point.get()->rational.x);rational(v.point.get()->rational.y);}else{const auto&p=*v.point.get()->algebraic.get();polynomial(p.function.get()->x);polynomial(p.function.get()->y);root(p.parameter);}rational(v.x.lower);rational(v.x.upper);rational(v.y.lower);rational(v.y.upper);}};
inline SABoundaryBudget budget(){SABoundaryBudget b{};b.max_commands=100;b.max_curves=64;b.max_pairs=1000;b.max_cuts=4096;b.max_edges=1024;b.max_leases=3;b.max_sources=8;b.max_paths=64;b.max_polynomial_degree=64;b.max_stored_bits=16384;b.max_polynomial_operations=50000000;b.max_limb_operations=1000000000;b.retained_bytes=b.workspace_bytes=8*1024*1024;return b;}
inline void rectangle(SAInkPathCommand*out,double x){SAInkPathCommand a[5]={{SA_INK_MOVE,0,{x,0}},{SA_INK_LINE,0,{x+1,0}},{SA_INK_LINE,0,{x+1,1}},{SA_INK_LINE,0,{x,1}},{SA_INK_CLOSE,0,{}}};copy_bytes(out,a,sizeof a);}
inline const Graph*source(void*state,SABoundaryLease lease){const auto*o=owner(state);return o&&o->valid(lease)?&o->slots[lease.slot].snapshot.get()->graph:nullptr;}
inline bool incidents(const Graph&g,uint32_t vertex,Writer&w,uint32_t expected_references,uint32_t expected_blocks){uint32_t refs=0,blocks=0;bool ok=vertex_incidents(g,vertex,[&](const IncidentNode<Edge>&n){auto actual=g.edges.chunk_record(n.slot);if(actual.get()!=n.block.get()||n.epoch!=g.output_epoch)return false;w.word(n.slot);w.wide(n.epoch);w.wide(n.block.get()->identity);w.wide(n.block.get()->revision);w.word(n.references);refs+=n.references;++blocks;return true;});w.word(refs);w.word(blocks);return ok&&refs==expected_references&&blocks==expected_blocks;}
}
extern "C" uint32_t sabt_vertex(uint32_t fixture,void*memory,uint32_t bytes,uint32_t*output,uint32_t capacity){
 using namespace showai_boundary;using namespace showai_boundary_vertex_test;if(fixture>2||!memory||((uintptr_t)memory&15u)||bytes<16*1024*1024+4096||!output||((uintptr_t)output&3u)||memory_overlap(memory,bytes,output,uint64_t(capacity)*4)||sa_boundary_state_bytes()>4096)return SA_INK_INVALID;
 Writer w;void*state=memory;void*arena=(uint8_t*)memory+4096;uint32_t arena_bytes=bytes-4096;for(uint32_t i=0;i<sa_boundary_state_bytes();i++)((uint8_t*)state)[i]=0;auto b=budget();if(sa_boundary_initialize(state,4096,100+fixture,arena,arena_bytes,&b))return SA_INK_RANGE;SABoundaryPath path{};SABoundarySourceBlock sources[2]{};for(uint32_t i=0;i<2;i++){sources[i].key.words[0]=i+1;sources[i].first_command=i*5;sources[i].command_count=5;sources[i].affine[0]=sources[i].affine[3]=1;}
 SABoundaryLease a{},next{},last{};
 if(fixture==0){SAInkPathCommand commands[10];rectangle(commands,0);rectangle(commands+5,3);if(sa_boundary_prepare(state,nullptr,&path,1,sources,2,commands,10,&a))return SA_INK_RANGE;{
  const auto&old=*source(state,a);const auto&e=old.edges.chunk(3)->values[0];auto before=vertex_certificate(old,e.va);if(!before.certificate.valid()||!before.certificate.get()->point.get()->exact())return SA_INK_RANGE;w.word(before.canonical);w.word(before.steps);w.certificate(before.certificate);if(!incidents(old,e.va,w,2,2))return SA_INK_RANGE;
  SABoundarySourceMutation mutation{};mutation.source=sources[1];mutation.source.first_command=0;rectangle(commands,6);if(sa_boundary_update(state,&a,&mutation,1,commands,5,&next))return SA_INK_RANGE;const auto&shifted=*source(state,next);auto preserved=vertex_certificate(shifted,e.va);if(preserved.certificate.get()!=before.certificate.get()||shifted.vertex_incidence[preserved.canonical].get()!=old.vertex_incidence[before.canonical].get())return SA_INK_RANGE;w.word(1);w.certificate(preserved.certificate);
  rectangle(commands,1);if(sa_boundary_update(state,&next,&mutation,1,commands,5,&last))return SA_INK_RANGE;const auto&joined=*source(state,last);auto after=vertex_certificate(joined,e.va);if(!after.certificate.valid()||after.certificate.get()->point.get()!=before.certificate.get()->point.get()||!joined.edges.same_chunk(3,old.edges))return SA_INK_RANGE;w.word(after.canonical);w.word(after.steps);w.certificate(after.certificate);if(!incidents(joined,e.va,w,2,2))return SA_INK_RANGE;uint32_t aliases=0;for(const auto&record:joined.point_aliases){const auto&alias=*record.get();if(alias.point.get()==before.certificate.get()->point.get()){if(!alias.after.valid()||alias.after.get()->point.get()!=alias.point.get()||(!alias.before_a.valid()&&!alias.before_b.valid()))return SA_INK_RANGE;w.wide(alias.a.valid()?alias.a.get()->identity:0);w.wide(alias.b.valid()?alias.b.get()->identity:0);w.wide(alias.point.get()->identity);w.word(alias.vertex_a);w.word(alias.vertex_b);w.word(alias.target);w.certificate(alias.after);++aliases;}}if(!aliases)return SA_INK_RANGE;w.word(aliases);
  SABoundaryLease untouched{1,2,3,4,5},failed=untouched;rectangle(commands,9);if(sa_boundary_update(state,&last,&mutation,1,commands,5,&failed)!=SA_INK_CAPACITY||([](const SABoundaryLease&a,const SABoundaryLease&b){const auto*x=(const uint8_t*)&a,*y=(const uint8_t*)&b;for(uint32_t i=0;i<sizeof(a);i++)if(x[i]!=y[i])return true;return false;})(failed,untouched))return SA_INK_RANGE;if(vertex_certificate(old,e.va).certificate.get()!=before.certificate.get())return SA_INK_RANGE;w.word(1);
 }if(sa_boundary_release(state,a)||sa_boundary_release(state,next)||sa_boundary_release(state,last))return SA_INK_RANGE;
 }else if(fixture==1){SAInkPathCommand commands[3]={{SA_INK_MOVE,0,{0,0}},{SA_INK_CUBIC,0,{1,1,-1,1,0,0}},{SA_INK_CLOSE,0,{}}};sources[0].command_count=3;if(sa_boundary_prepare(state,nullptr,&path,1,sources,1,commands,3,&a))return SA_INK_RANGE;{
  const auto&g=*source(state,a);if(g.edges.chunk_count()!=1||g.edges.empty())return SA_INK_RANGE;const auto&first=g.edges[0];const auto&tail=g.edges[g.edges.size()-1];auto p=vertex_certificate(g,first.va),q=vertex_certificate(g,tail.vb);if(!p.certificate.valid()||p.certificate.get()!=q.certificate.get())return SA_INK_RANGE;w.word(p.canonical);w.word(p.steps);w.certificate(p.certificate);if(!incidents(g,first.va,w,2,1))return SA_INK_RANGE;w.word(g.edges.size());
 }if(sa_boundary_release(state,a))return SA_INK_RANGE;
 }else{SABoundaryPath paths[2]={{0,0,{0,0}},{0,1,{0,0}}};SAInkPathCommand commands[8]={{SA_INK_MOVE,0,{0,0}},{SA_INK_QUAD,0,{.5,1,1,0}},{SA_INK_CLOSE,0,{}},{SA_INK_MOVE,0,{-1,.25}},{SA_INK_LINE,0,{2,.25}},{SA_INK_LINE,0,{2,2}},{SA_INK_LINE,0,{-1,2}},{SA_INK_CLOSE,0,{}}};sources[0].command_count=3;sources[1].path_index=1;sources[1].first_command=3;sources[1].command_count=5;if(sa_boundary_prepare(state,nullptr,paths,2,sources,2,commands,8,&a))return SA_INK_RANGE;{
  Record<VertexCertificate>certificate;const auto&old=*source(state,a);for(const auto&e:old.edges){auto found=vertex_certificate(old,e.va);if(found.certificate.valid()&&!found.certificate.get()->point.get()->exact()){certificate=found.certificate;break;}}if(!certificate.valid())return SA_INK_RANGE;auto authority=certificate.get()->point;const auto&point=*authority.get()->algebraic.get();Interval x=evaluate(point.function.get()->x,{point.parameter.lower,point.parameter.upper});w.certificate(certificate);
  SABoundarySourceMutation mutation{};mutation.source=sources[0];commands[1].values[0]=1;commands[1].values[2]=2;if(sa_boundary_update(state,&a,&mutation,1,commands,3,&next)||sa_boundary_release(state,a))return SA_INK_RANGE;const auto&retained=*authority.get()->algebraic.get();Interval again=evaluate(retained.function.get()->x,{retained.parameter.lower,retained.parameter.upper});if(!exact_equal(x.lower,again.lower)||!exact_equal(x.upper,again.upper))return SA_INK_RANGE;w.word(1);w.certificate(certificate);
 }if(sa_boundary_release(state,next))return SA_INK_RANGE;
 }
 if(sa_boundary_destroy(state))return SA_INK_RANGE;for(uint32_t i=0;i<sa_boundary_state_bytes();i++)if(((uint8_t*)state)[i])return SA_INK_RANGE;if(!w.good||w.size>capacity)return SA_INK_CAPACITY;w.values[0]=w.size;for(uint32_t i=0;i<w.size;i++)output[i]=w.values[i];return SA_INK_OK;
}
#endif
